-- Runs ONLY in a disposable PostgreSQL CI database.
BEGIN;
SELECT pg_catalog.set_config('app.test_uid', '20000000-0000-0000-0000-000000000001', true);
SELECT pg_catalog.set_config('app.test_school', '10000000-0000-0000-0000-000000000001', true);


VALUES ('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-000000000005','80000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001'),
       ('10000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-000000000006','80000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002');


-- Candidate regression suite. Run only after loading the draft SQL on a disposable schema.
UPDATE public.turmas SET tempo_lectivo_minutos=45 WHERE escola_id='10000000-0000-0000-0000-000000000001';
DO $tests$
DECLARE s uuid:='10000000-0000-0000-0000-000000000001';
 p uuid:='40000000-0000-0000-0000-000000000001';
 t uuid:='b0000000-0000-0000-0000-000000000001';
 m uuid:='a0000000-0000-0000-0000-000000000005'; n integer;
BEGIN
 IF NOT public.teacher_workload_exceeds(s,t,17,765,4,20,NULL) THEN RAISE EXCEPTION 'LEGACY_LIMIT_CHANGED'; END IF;
 IF public.teacher_workload_exceeds(s,t,17,765,4,20,1200) THEN RAISE EXCEPTION 'CLOCK_HOURS_FALSE_POSITIVE'; END IF;
 IF NOT public.teacher_workload_exceeds(s,t,26,1170,1,20,1200) THEN RAISE EXCEPTION 'CLOCK_HOURS_OVERFLOW'; END IF;
 IF public.teacher_workload_exceeds(s,t,25,1125,1,20,1200) THEN RAISE EXCEPTION 'CLOCK_HOURS_BOUNDARY'; END IF;
 PERFORM public.configure_teacher_workload_atomic(s,p,'minutos',1200,1200);
 SELECT public.assign_teacher_regime_atomic(s,t,'monodocencia',p,NULL) INTO n;
 IF n<>1 THEN RAISE EXCEPTION 'MONODOCENCIA_COUNT'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.turmas WHERE id=t AND professor_titular_id=p AND regime_docencia='monodocencia') THEN RAISE EXCEPTION 'MISSING_TITULAR'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.turma_disciplinas WHERE turma_id=t AND curso_matriz_id=m AND professor_id=p) THEN RAISE EXCEPTION 'MISSING_LINK'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.get_teacher_workload_config(s,p) w WHERE w.unidade='minutos' AND w.limite=1200 AND w.tempos_atribuidos=2 AND w.minutos_atribuidos=90) THEN RAISE EXCEPTION 'LOAD_PROJECTION_MISMATCH'; END IF;
 -- A conflicting owner must roll back the attempted regime.
 BEGIN
   PERFORM public.assign_teacher_regime_atomic(s,t,'monodocencia','40000000-0000-0000-0000-000000000002',NULL);
   RAISE EXCEPTION 'EXPECTED_CONFLICT';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'ASSIGN_PROF_ALREADY_ASSIGNED%' THEN RAISE; END IF; END;
 IF NOT EXISTS (SELECT 1 FROM public.turmas WHERE id=t AND professor_titular_id=p) THEN RAISE EXCEPTION 'REGIME_PARTIAL_WRITE'; END IF;
END $tests$;
SELECT pg_catalog.set_config('app.test_uid','20000000-0000-0000-0000-000000000002',true);
DO $tests$ BEGIN
 BEGIN
  PERFORM public.configure_teacher_workload_atomic('10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','minutos',1200,1200);
  RAISE EXCEPTION 'EXPECTED_FORBIDDEN';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'TEACHER_LOAD_FORBIDDEN%' THEN RAISE; END IF; END;
END $tests$;
ROLLBACK;
